<!DOCTYPE html>
<html lang="es">

<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Extensión de Línea de Crédito — Padcolor</title>
<script src="https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js"></script>
<style>
  :root{
    --blue:       #0014a0;
    --blue-dk:    #000d7a;
    --blue-md:    #1a30c0;
    --blue-lt:    #e8eafb;
    --blue-xl:    #f0f2ff;
    --magenta:    #cc0fdd;
    --magenta-lt: #fdf0ff;
    --green:      #16a34a;
    --green-lt:   #f0fdf4;
    --red:        #dc2626;
    --red-lt:     #fef2f2;
    --amber:      #d97706;
    --amber-lt:   #fffbeb;
    --gray:       #6b7280;
    --border:     #d1d5db;
    --bg:         #f0f2ff;
    --white:      #ffffff;
    --radius:     10px;
    --shadow:     0 2px 16px rgba(0,20,160,.10);
  }
  *{box-sizing:border-box;margin:0;padding:0}
  body{font-family:'Segoe UI',Arial,sans-serif;background:var(--bg);color:#1e293b;min-height:100vh}

  /* HEADER */
  .hdr{background:var(--blue);padding:0;position:sticky;top:0;z-index:100;
         box-shadow:0 2px 10px rgba(0,20,160,.35)}
  .hdr-inner{max-width:880px;margin:0 auto;padding:10px 20px;
              display:flex;align-items:center;gap:16px}
  .hdr-logo{height:52px;width:auto;display:block}
  .hdr-divider{width:1px;height:42px;background:rgba(255,255,255,.25)}
  .hdr-text .t1{color:#fff;font-size:1.05rem;font-weight:700;letter-spacing:-.01em}
  .hdr-text .t2{color:rgba(255,255,255,.65);font-size:.78rem;margin-top:2px}

  /* MAIN */
  .main{max-width:880px;margin:0 auto;padding:24px 14px 80px}

  /* INTRO BADGE */
  .intro-badge{
    display:inline-flex;align-items:center;gap:8px;
    background:var(--magenta-lt);border:1.5px solid var(--magenta);
    border-radius:20px;padding:6px 14px;font-size:.82rem;
    color:#6b007a;font-weight:600;margin-bottom:20px
  }
  .intro-badge::before{content:'🔵';font-size:.9rem}

  /* SECCIÓN */
  .sec{background:var(--white);border-radius:var(--radius);
        box-shadow:var(--shadow);margin-bottom:18px;overflow:visible}
  .sec-hdr{
    background:var(--blue);color:#fff;padding:13px 18px;
    display:flex;align-items:center;gap:11px;
    cursor:pointer;user-select:none;border-radius:var(--radius) var(--radius) 0 0;
    transition:background .15s
  }
  .sec-hdr:hover:not(.locked){background:var(--blue-md)}
  .sec-hdr.locked{background:#94a3b8;cursor:default}
  .sec-num{
    width:26px;height:26px;border-radius:50%;
    background:rgba(255,255,255,.22);
    display:flex;align-items:center;justify-content:center;
    font-weight:700;font-size:.85rem;flex-shrink:0
  }
  .sec-num.done{background:var(--green)}
  .sec-title{font-weight:600;font-size:.97rem;flex:1}
  .sec-chev{font-size:1rem;transition:transform .2s;margin-left:auto}
  .sec-body{padding:22px 18px;display:none}
  .sec-body.open{display:block}

  /* BUSCADOR DE CLIENTE */
  .search-box{
    background:var(--blue-xl);border:2px solid var(--blue);
    border-radius:var(--radius);padding:18px;margin-bottom:6px;position:relative
  }
  .search-box h3{color:var(--blue);font-size:.93rem;font-weight:700;margin-bottom:14px;
                  display:flex;align-items:center;gap:7px}
  .search-box h3::before{content:'🔍';font-size:.85rem}
  .three-fields{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;margin-bottom:14px}
  @media(max-width:620px){.three-fields{grid-template-columns:1fr}}
  .field-wrap{position:relative;display:flex;flex-direction:column;gap:5px}
  .field-wrap label{font-size:.8rem;font-weight:700;color:#374151;
                     display:flex;align-items:center;gap:5px}
  .badge-2of3{
    display:inline-block;background:var(--blue);color:#fff;
    border-radius:8px;padding:1px 6px;font-size:.68rem;font-weight:700
  }
  input.field-inp{
    border:1.5px solid var(--border);border-radius:7px;padding:9px 11px;
    font-size:.9rem;font-family:inherit;color:#1e293b;background:#fff;
    transition:border-color .15s,box-shadow .15s;width:100%
  }
  input.field-inp:focus{outline:none;border-color:var(--blue);
    box-shadow:0 0 0 3px rgba(0,20,160,.12)}
  input.field-inp.ok{border-color:var(--green)!important}
  input.field-inp.err{border-color:var(--red)!important}

  /* AUTOCOMPLETE DROPDOWN */
  .ac-wrap{position:relative}
  .ac-dropdown{
    position:absolute;top:calc(100% + 3px);left:0;right:0;
    background:#fff;border:1.5px solid var(--blue);border-radius:8px;
    box-shadow:0 6px 24px rgba(0,20,160,.18);z-index:50;
    max-height:220px;overflow-y:auto;display:none
  }
  .ac-dropdown.open{display:block}
  .ac-item{
    padding:9px 12px;font-size:.87rem;cursor:pointer;
    border-bottom:1px solid #f0f0f0;line-height:1.35
  }
  .ac-item:last-child{border-bottom:none}
  .ac-item:hover,.ac-item.active{background:var(--blue-lt)}
  .ac-item .ac-rs{font-weight:600;color:#1e293b}
  .ac-item .ac-sub{font-size:.77rem;color:var(--gray)}
  .ac-no-results{padding:10px 12px;font-size:.85rem;color:var(--gray);font-style:italic}

  /* INDICADOR 2 DE 3 */
  .verify-indicator{
    display:flex;align-items:center;gap:10px;
    background:#fff;border:1.5px solid var(--border);
    border-radius:8px;padding:10px 14px;margin-bottom:12px
  }
  .verify-dots{display:flex;gap:6px}
  .vdot{
    width:14px;height:14px;border-radius:50%;
    background:var(--border);transition:background .2s
  }
  .vdot.filled{background:var(--blue)}
  .vdot.done{background:var(--green)}
  .verify-label{font-size:.83rem;color:var(--gray);font-weight:600;flex:1}
  .verify-label.ready{color:var(--green)}

  /* BTN VERIFICAR */
  .btn-verificar{
    background:var(--blue);color:#fff;border:none;border-radius:7px;
    padding:10px 22px;font-size:.9rem;font-weight:700;cursor:pointer;
    transition:background .15s;width:100%
  }
  .btn-verificar:hover{background:var(--blue-dk)}
  .btn-verificar:disabled{background:#94a3b8;cursor:not-allowed}

  /* CARD CLIENTE */
  .cliente-card{
    background:var(--blue-lt);border:2px solid var(--blue);
    border-radius:var(--radius);padding:15px 17px;margin-top:10px
  }
  .cliente-card .cli-nombre{
    font-size:1rem;font-weight:700;color:var(--blue);
    margin-bottom:9px;display:flex;align-items:center;gap:8px;flex-wrap:wrap
  }
  .badge-activo{background:#dcfce7;color:var(--green);border:1px solid #86efac;
                 border-radius:4px;padding:1px 7px;font-size:.73rem;font-weight:700}
  .badge-bloq{background:#fee2e2;color:var(--red);border:1px solid #fca5a5;
               border-radius:4px;padding:1px 7px;font-size:.73rem;font-weight:700}
  .cli-grid{display:grid;grid-template-columns:1fr 1fr;gap:5px 18px}
  @media(max-width:480px){.cli-grid{grid-template-columns:1fr}}
  .cli-item{font-size:.83rem}
  .cli-item b{color:#374151}
  .btn-cambiar{
    margin-top:12px;background:none;border:1.5px solid var(--blue);
    color:var(--blue);border-radius:6px;padding:6px 14px;
    font-size:.82rem;font-weight:600;cursor:pointer;transition:all .15s
  }
  .btn-cambiar:hover{background:var(--blue);color:#fff}
  .search-error{color:var(--red);font-size:.85rem;font-weight:600;margin-top:8px;display:none}

  /* FORM ELEMENTS */
  .form-row{display:flex;gap:12px;margin-bottom:12px;flex-wrap:wrap}
  .fg{display:flex;flex-direction:column;gap:4px;flex:1;min-width:150px}
  .fg.full{flex-basis:100%}
  .fg.half{flex:0 0 calc(50% - 6px)}
  .fg.third{flex:0 0 calc(33.33% - 9px)}
  @media(max-width:580px){.fg.half,.fg.third{flex-basis:100%}}
  .fg label{font-size:.8rem;font-weight:700;color:#374151}
  .fg label .req{color:var(--red)}
  .fg input,.fg select,.fg textarea{
    border:1.5px solid var(--border);border-radius:7px;padding:9px 11px;
    font-size:.9rem;font-family:inherit;color:#1e293b;background:#fff;
    transition:border-color .15s,box-shadow .15s;width:100%
  }
  .fg input:focus,.fg select:focus{
    outline:none;border-color:var(--blue);
    box-shadow:0 0 0 3px rgba(0,20,160,.10)
  }
  .subsec{
    font-size:.78rem;font-weight:800;color:var(--blue);text-transform:uppercase;
    letter-spacing:.05em;margin:16px 0 10px;
    padding-bottom:5px;border-bottom:2px solid var(--blue-lt)
  }

  /* MONTO */
  .monto-card{
    background:var(--amber-lt);border:2px solid #fcd34d;
    border-radius:var(--radius);padding:16px 18px;margin-bottom:12px
  }
  .monto-card h3{color:#92400e;font-size:.9rem;font-weight:700;margin-bottom:12px}
  .monto-prefix-wrap{position:relative;margin-bottom:10px}
  .monto-prefix{
    position:absolute;left:11px;top:50%;transform:translateY(-50%);
    color:var(--gray);font-size:1rem;pointer-events:none
  }
  .monto-prefix-wrap input{padding-left:22px}
  .monto-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:12px}
  @media(max-width:600px){.monto-grid{grid-template-columns:1fr 1fr}}
  .monto-box{background:#fff;border:1.5px solid #fcd34d;border-radius:8px;
              padding:9px 12px;text-align:center}
  .monto-box .ml{font-size:.72rem;color:var(--gray);margin-bottom:3px}
  .monto-box .mv{font-size:1rem;font-weight:700;color:var(--blue)}
  .monto-box.destacado .mv{color:var(--green);font-size:1.1rem}

  /* ADJUNTOS */
  .adj-group{
    border:1.5px dashed var(--border);border-radius:8px;
    padding:12px 14px;margin-bottom:10px;background:#fafbfc
  }
  .adj-group label{font-size:.83rem;font-weight:700;color:#374151;
                    margin-bottom:5px;display:block}
  .adj-group .hint{font-size:.76rem;color:var(--gray);margin-top:3px}
  .adj-ok{color:var(--green);font-size:.8rem;margin-top:3px;
           display:none;font-weight:600}
  input[type=file]{border:none;padding:0;background:transparent;
                    font-size:.83rem;cursor:pointer;width:100%}

  /* PAGARÉ STEPS */
  .pagare-steps{
    background:#f7f9ff;border:1.5px solid #c7d4f8;
    border-radius:8px;padding:13px 15px;margin-bottom:12px
  }
  .pagare-steps p{font-size:.85rem;color:#374151;line-height:1.5;margin-bottom:5px}
  .pagare-steps strong{color:var(--blue)}
  .btn-pagare{
    background:var(--blue);color:#fff;border:none;border-radius:7px;
    padding:9px 18px;font-size:.88rem;font-weight:700;cursor:pointer;
    display:inline-flex;align-items:center;gap:7px;margin:6px 0 12px;
    transition:background .15s
  }
  .btn-pagare:hover{background:var(--blue-dk)}
  .btn-pagare:disabled{background:#94a3b8;cursor:not-allowed}

  /* FOOTER */
  .footer{
    position:fixed;bottom:0;left:0;right:0;
    background:#fff;border-top:2px solid var(--blue-lt);
    padding:11px 14px;z-index:99;
    box-shadow:0 -2px 12px rgba(0,20,160,.10)
  }
  .footer-inner{max-width:880px;margin:0 auto;display:flex;align-items:center;gap:14px;flex-wrap:wrap}
  .btn-submit{
    background:var(--blue);color:#fff;border:none;border-radius:8px;
    padding:12px 28px;font-size:.97rem;font-weight:700;cursor:pointer;
    transition:background .15s;white-space:nowrap
  }
  .btn-submit:hover{background:var(--blue-dk)}
  .btn-submit:disabled{background:#94a3b8;cursor:not-allowed}
  .footer-err{color:var(--red);font-size:.86rem;font-weight:600;flex:1}

  /* MODAL */
  .modal-ov{display:none;position:fixed;inset:0;background:rgba(0,0,0,.48);
             z-index:200;align-items:center;justify-content:center}
  .modal-ov.open{display:flex}
  .modal{background:#fff;border-radius:14px;max-width:520px;width:92%;
          padding:26px 22px;box-shadow:0 8px 32px rgba(0,0,0,.22);
          max-height:90vh;overflow-y:auto}
  .modal h2{color:var(--blue);font-size:1.15rem;margin-bottom:14px}
  .modal p{font-size:.89rem;line-height:1.6;margin-bottom:9px}
  .modal a{color:var(--blue);font-weight:600}
  .modal .hl-box{
    background:var(--blue-lt);border:1.5px solid #a5b4fc;
    border-radius:8px;padding:11px 13px;margin:10px 0;
    font-size:.87rem;line-height:1.6
  }
  .btn-cls{
    background:var(--blue);color:#fff;border:none;border-radius:7px;
    padding:10px 22px;font-size:.9rem;font-weight:700;cursor:pointer;
    margin-top:12px;transition:background .15s
  }
  .btn-cls:hover{background:var(--blue-dk)}

  /* TOAST */
  #toast{
    position:fixed;top:76px;right:18px;z-index:300;
    background:#1e293b;color:#fff;border-radius:8px;
    padding:9px 16px;font-size:.86rem;
    opacity:0;pointer-events:none;transition:opacity .25s;max-width:300px
  }
  #toast.show{opacity:1}
  #toast.ok{background:var(--green)}
  #toast.er{background:var(--red)}

  .tipo-wrap{display:flex;gap:10px;margin-bottom:12px}
  .tipo-btn{
    flex:1;padding:10px 8px;border:2px solid var(--border);
    border-radius:8px;background:#fff;cursor:pointer;
    font-size:.88rem;font-weight:600;color:#374151;
    display:flex;align-items:center;justify-content:center;gap:8px;
    transition:all .18s;user-select:none
  }
  .tipo-btn:hover{border-color:var(--blue);color:var(--blue);background:var(--blue-xl)}
  .tipo-btn.selected{border-color:var(--blue);background:var(--blue);color:#fff}
  .tipo-icon{font-size:1.1rem}
  .tipo-hint{font-size:.78rem;color:var(--red);margin-bottom:8px;display:none}
  .tipo-hint.visible{display:block}

</style>
</head>
<body>

<header class="hdr">
  <div class="hdr-inner">
    <img class="hdr-logo" src="data:image/jpeg;base64," alt="PadColor">
    <div class="hdr-divider"></div>
    <div class="hdr-text">
      <div class="t1">Extensión de Línea de Crédito</div>
      <div class="t2">Papel, Diseño y Color S.A. de C.V. &mdash; Catálogo Siman &mdash; Clientes vigentes</div>
    </div>
  </div>
</header>

<main class="main">
  <div class="intro-badge">Completa los 5 pasos para generar tu expediente de solicitud</div>

  <!-- ── SEC 1: IDENTIFICACIÓN ── -->
  <div class="sec" id="sec-1">
    <div class="sec-hdr" onclick="toggleSec(1)">
      <div class="sec-num" id="snum-1">1</div>
      <div class="sec-title">Identificación del cliente</div>
      <div class="sec-chev" id="schev-1">▾</div>
    </div>
    <div class="sec-body open" id="sbody-1">

      <div class="search-box" id="search-panel">
        <h3>Busca tu cuenta &mdash; proporciona 2 de 3 datos</h3>

        <!-- indicador 2 de 3 -->
        <div class="verify-indicator" id="verify-ind">
          <div class="verify-dots">
            <div class="vdot" id="vdot-0"></div>
            <div class="vdot" id="vdot-1"></div>
            <div class="vdot" id="vdot-2"></div>
          </div>
          <div class="verify-label" id="verify-lbl">Llena al menos 2 de los 3 campos para verificar</div>
        </div>

        <div class="three-fields">
          <!-- Razón social con autocomplete -->
          <div class="field-wrap">
            <label>Razón social <span class="badge-2of3">2 de 3</span></label>
            <div class="ac-wrap" id="ac-wrap">
              <input class="field-inp" id="inp-rs" type="text"
                     placeholder="Escribe tu razón social…"
                     autocomplete="off" spellcheck="false"
                     oninput="onRsInput()" onkeydown="onRsKey(event)" onfocus="onRsFocus()">
              <div class="ac-dropdown" id="ac-drop"></div>
            </div>
          </div>

          <!-- Número de cliente -->
          <div class="field-wrap">
            <label>Número de cliente <span class="badge-2of3">2 de 3</span></label>
            <input class="field-inp" id="inp-num" type="text"
                   placeholder="Ej. 102-01-00331"
                   autocomplete="off" autocapitalize="characters"
                   oninput="onFieldInput()" onkeydown="if(event.key==='Enter')verificar()">
          </div>

          <!-- RFC -->
          <div class="field-wrap">
            <label>RFC <span class="badge-2of3">2 de 3</span></label>
            <input class="field-inp" id="inp-rfc" type="text"
                   placeholder="Ej. ZMP950530BN1"
                   maxlength="13" autocomplete="off" autocapitalize="characters"
                   oninput="this.value=this.value.toUpperCase();onFieldInput()"
                   onkeydown="if(event.key==='Enter')verificar()">
          </div>
        </div>

        <div style="margin-bottom:5px">
          <label style="font-size:.8rem;font-weight:700;color:#374151">Tipo de persona <span style="color:var(--red)">*</span></label>
        </div>
        <div class="tipo-wrap">
          <button class="tipo-btn" id="tipo-fisica" onclick="selTipo('fisica')" type="button">
            <span class="tipo-icon">👤</span> Persona Física
          </button>
          <button class="tipo-btn" id="tipo-moral" onclick="selTipo('moral')" type="button">
            <span class="tipo-icon">🏢</span> Persona Moral
          </button>
        </div>
        <div class="tipo-hint" id="tipo-hint">Selecciona el tipo de persona para continuar.</div>
        <div class="search-error" id="search-err"></div>
        <button class="btn-verificar" id="btn-verificar" onclick="verificar()" disabled>
          Verificar →
        </button>
      </div>

      <!-- CARD resultado -->
      <div id="cliente-card" style="display:none"></div>

    </div>
  </div>

  <!-- ── SEC 2: MONTO ── -->
  <div class="sec" id="sec-2">
    <div class="sec-hdr locked" id="shdr-2">
      <div class="sec-num" id="snum-2">2</div>
      <div class="sec-title">Monto de crédito solicitado</div>
      <div class="sec-chev" id="schev-2">▾</div>
    </div>
    <div class="sec-body" id="sbody-2">
      <div class="monto-card">
        <h3>¿Cuál es la línea de crédito que solicitas?</h3>
        <div class="monto-prefix-wrap">
          <span class="monto-prefix">$</span>
          <input type="number" class="field-inp" id="monto-sol"
                 min="1" step="0.01" placeholder="0.00"
                 style="padding-left:22px" oninput="actualizarMonto()">
        </div>
        <div class="monto-grid">
          <div class="monto-box">
            <div class="ml">Línea actual</div>
            <div class="mv" id="m-lc">—</div>
          </div>
          <div class="monto-box">
            <div class="ml">Saldo actual</div>
            <div class="mv" id="m-sa">—</div>
          </div>
          <div class="monto-box">
            <div class="ml">Línea adicional</div>
            <div class="mv" id="m-adicional">—</div>
          </div>
          <div class="monto-box destacado">
            <div class="ml">Nueva línea resultante</div>
            <div class="mv" id="m-nueva">—</div>
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- ── SEC 3: SOLICITANTE ── -->
  <div class="sec" id="sec-3">
    <div class="sec-hdr locked" id="shdr-3">
      <div class="sec-num" id="snum-3">3</div>
      <div class="sec-title">Datos del solicitante firmante (representante legal)</div>
      <div class="sec-chev" id="schev-3">▾</div>
    </div>
    <div class="sec-body" id="sbody-3">
      <div class="subsec">Persona moral o física</div>
      <div class="form-row">
        <div class="fg full">
          <label>Nombre completo (persona moral o física) <span class="req">*</span></label>
          <input type="text" id="cred-razon-social"
                 placeholder="Razón social o nombre tal como aparece en el RFC">
        </div>
      </div>
      <div class="subsec">Datos del firmante (representante legal)</div>
      <div class="form-row">
        <div class="fg half">
          <label>Nombre(s) <span class="req">*</span></label>
          <input type="text" id="cred-sol-nombres" placeholder="Nombres">
        </div>
        <div class="fg third">
          <label>Apellido paterno <span class="req">*</span></label>
          <input type="text" id="cred-sol-paterno" placeholder="Apellido paterno">
        </div>
        <div class="fg third">
          <label>Apellido materno</label>
          <input type="text" id="cred-sol-materno" placeholder="Apellido materno">
        </div>
      </div>
      <div class="form-row">
        <div class="fg half">
          <label>Correo electrónico <span class="req">*</span></label>
          <input type="email" id="cred-sol-email" placeholder="correo@ejemplo.com">
        </div>
        <div class="fg half">
          <label>Teléfono móvil (10 dígitos) <span class="req">*</span></label>
          <input type="tel" id="cred-sol-tel" placeholder="(33) 1234 5678"
                 maxlength="14" oninput="maskPhone(this)">
        </div>
      </div>
      <div class="subsec">Dirección del solicitante (de la persona física o de la persona moral)</div>
      <div class="form-row">
        <div class="fg" style="flex:2">
          <label>Calle <span class="req">*</span></label>
          <input type="text" id="cred-sol-calle" placeholder="Nombre de la calle">
