// Índices de búsqueda
const IDX_NUM  = {};   // número → cliente
const IDX_RFC  = {};   // RFC → [clientes]
CLIENTES.forEach(c => {
  IDX_NUM[c.n.toUpperCase()] = c;
  const r = (c.rfc||'').toUpperCase();
  if(r){
    if(!IDX_RFC[r]) IDX_RFC[r] = [];
    IDX_RFC[r].push(c);
  }
});

// Estado
let state = { cliente: null, tipoPersona: null, acSelIdx: -1, acResults: [] };

// ── UTILS ──
const $ = id => document.getElementById(id);
const fmt = n => Number(n||0).toLocaleString('es-MX',{minimumFractionDigits:2,maximumFractionDigits:2});

function toast(msg, tipo='ok'){
  const el=$('toast');
  el.textContent=msg; el.className='show '+tipo;
  clearTimeout(el._t);
  el._t=setTimeout(()=>el.className='',3000);
}
function showModal(t,h){$('modal-ttl').textContent=t;$('modal-body').innerHTML=h;$('modal-ov').classList.add('open');}
function cerrarModal(){$('modal-ov').classList.remove('open');}
function markAdj(inputId,okId){
  const f=$(inputId).files[0];
  $(okId).style.display=f?'block':'none';
}
function maskPhone(inp){
  let d=inp.value.replace(/\D/g,'').substring(0,10),o='';
  if(d.length>0) o='('+d.substring(0,2);
  if(d.length>2) o+=') '+d.substring(2,6);
  if(d.length>6) o+=' '+d.substring(6,10);
  inp.value=o;
}
function armarDir(o){
  return [o.calle,o.numext?'No.'+o.numext:'',o.numint?'Int.'+o.numint:'',
          o.colonia?'Col. '+o.colonia:'',o.ciudad,o.estado,
          o.cp?'C.P. '+o.cp:'',o.pais].filter(Boolean).join(', ');
}

// ── SECCIONES ──
function toggleSec(n){
  const hdr=$('shdr-'+n);
  if(hdr&&hdr.classList.contains('locked')) return;
  const body=$('sbody-'+n), chev=$('schev-'+n);
  const open=body.classList.toggle('open');
  chev.style.transform=open?'rotate(0deg)':'rotate(-90deg)';
}
function unlockSec(n){
  const hdr=$('shdr-'+n);
  if(!hdr||!hdr.classList.contains('locked')) return;
  hdr.classList.remove('locked');
  hdr.onclick=()=>toggleSec(n);
  $('sbody-'+n).classList.add('open');
}
function doneSec(n){
  const el=$('snum-'+n);
  el.classList.add('done'); el.textContent='✓';
}

// ── AUTOCOMPLETE RAZÓN SOCIAL ──
function normalizar(s){
  return (s||'').toUpperCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^A-Z0-9 ]/g,' ').replace(/ +/g,' ').trim();
}

// ── AUTOCOMPLETE ──
let acDebounce = null;
function onRsInput(){
  clearTimeout(acDebounce);
  acDebounce = setTimeout(()=>{
    const q = normalizar($('inp-rs').value);
    if(q.length < 2){ cerrarAC(); onFieldInput(); return; }
    const tokens = q.split(' ').filter(Boolean);
    const matches = [];
    for(const c of CLIENTES){
      if(matches.length >= 12) break;
      const rs = normalizar(c.rs);
      if(tokens.every(t => rs.includes(t))) matches.push(c);
    }
    state.acResults = matches;
    state.acSelIdx = -1;
    renderAC(matches, $('inp-rs').value);
    onFieldInput();
  }, 180);
}

function onRsFocus(){
  if(normalizar($('inp-rs').value).length >= 2) onRsInput();
}

function renderAC(results, query){
  const drop = $('ac-drop');
  if(!results.length){
    drop.innerHTML = query.length>=2 ? '<div class="ac-no-results">Sin coincidencias</div>' : '';
    drop.classList.toggle('open', query.length>=2);
    return;
  }
  drop.innerHTML = results.map((c,i) =>
    `<div class="ac-item" data-idx="${i}"
         onmousedown="seleccionarAC(${i})"
         onmouseover="this.classList.add('active')"
         onmouseout="this.classList.remove('active')">
      <div class="ac-rs">${esc(c.rs)}</div>
      <div class="ac-sub">${esc(c.n)} &bull; RFC: ${esc(c.rfc||'—')}</div>
    </div>`).join('');
  drop.classList.add('open');
}

function seleccionarAC(idx){
  const c = state.acResults[idx];
  if(!c) return;
  $('inp-rs').value = c.rs;
  cerrarAC();
  onFieldInput();
}

function cerrarAC(){
  $('ac-drop').classList.remove('open');
  state.acSelIdx = -1;
}

function onRsKey(e){
  const drop = $('ac-drop');
  if(!drop.classList.contains('open')) return;
  const items = drop.querySelectorAll('.ac-item');
  if(e.key==='ArrowDown'){
    e.preventDefault();
    state.acSelIdx = Math.min(state.acSelIdx+1, items.length-1);
    items.forEach((el,i)=>el.classList.toggle('active', i===state.acSelIdx));
  } else if(e.key==='ArrowUp'){
    e.preventDefault();
    state.acSelIdx = Math.max(state.acSelIdx-1, 0);
    items.forEach((el,i)=>el.classList.toggle('active', i===state.acSelIdx));
  } else if(e.key==='Enter'){
    e.preventDefault();
    if(state.acSelIdx>=0 && state.acResults[state.acSelIdx]){
      seleccionarAC(state.acSelIdx);
    } else { cerrarAC(); verificar(); }
  } else if(e.key==='Escape'){
    cerrarAC();
  }
}

document.addEventListener('click', e=>{
  if(!$('ac-wrap').contains(e.target)) cerrarAC();
});

// ── INDICADOR 2 DE 3 ──
function onFieldInput(){
  const rsV  = ($('inp-rs').value||'').trim();
  const numV = ($('inp-num').value||'').trim();
  const rfcV = ($('inp-rfc').value||'').trim();
  const filled = [rsV, numV, rfcV].filter(Boolean).length;
  ['vdot-0','vdot-1','vdot-2'].forEach((id,i)=>{
    $(id).className = 'vdot' + (i < filled ? ' filled' : '');
  });
  const lbl = $('verify-lbl');
  if(filled >= 2){
    lbl.textContent = 'Listo para verificar';
    lbl.className = 'verify-label ready';
  } else {
    lbl.textContent = `Llena al menos ${2 - filled} campo(s) más para verificar`;
    lbl.className = 'verify-label';
  }
  $('btn-verificar').disabled = !(filled >= 2 && state.tipoPersona);
  $('search-err').style.display = 'none';
}

function selTipo(tipo) {
  state.tipoPersona = tipo;
  $('tipo-fisica').classList.toggle('selected', tipo === 'fisica');
  $('tipo-moral').classList.toggle('selected', tipo === 'moral');
  $('tipo-hint').classList.remove('visible');
  $('poder-wrap').style.display = tipo === 'moral' ? 'block' : 'none';
  if(tipo === 'fisica') { $('cred-poder').value = ''; $('ok-poder').style.display='none'; }
  onFieldInput();
}

// ── VERIFICACIÓN 2 DE 3 (algoritmo de puntuación combinada) ──
// Cada campo provisto suma +1 al score de cada cliente que lo coincide.
// Se activa el cliente con score >= 2.
// El campo faltante se auto-rellena con el dato del cliente ganador.
function verificar(){
  if(!state.tipoPersona){ $('tipo-hint').classList.add('visible'); return; }
  const numRaw = ($('inp-num').value||'').trim().toUpperCase();
  const rfcRaw = ($('inp-rfc').value||'').trim().toUpperCase();
  const rsRaw  = ($('inp-rs').value||'').trim();
  const rsNorm = normalizar(rsRaw);
  const errEl  = $('search-err');

  // Mapa de scores: clienteN → {cliente, score}
  const scores = {};

  function sumar(c, puntos){
    if(!scores[c.n]) scores[c.n] = {c, s: 0};
    scores[c.n].s += puntos;
  }

  // Campo 1: número de cliente (coincidencia exacta)
  if(numRaw){
    const c = IDX_NUM[numRaw];
    if(c) sumar(c, 1);
  }

  // Campo 2: RFC (coincidencia exacta)
  if(rfcRaw){
    const arr = IDX_RFC[rfcRaw] || [];
    arr.forEach(c => sumar(c, 1));
  }

  // Campo 3: razón social (coincidencia por tokens)
  if(rsNorm.length >= 3){
    const tokens = rsNorm.split(' ').filter(Boolean);
    for(const c of CLIENTES){
      const rs = normalizar(c.rs);
      if(tokens.every(t => rs.includes(t))) sumar(c, 1);
    }
  }

  // Buscar el cliente con mayor score
  let mejor = null, mejorScore = 0;
  for(const entry of Object.values(scores)){
    if(entry.s > mejorScore){ mejorScore = entry.s; mejor = entry.c; }
  }

  if(!mejor || mejorScore < 2){
    let msg = 'Los datos no coinciden con ningún cliente registrado.';
    if(numRaw && !IDX_NUM[numRaw])
      msg = 'El número de cliente no existe en el catálogo. Verifica el formato (ej. 102-01-00331).';
    else if(rfcRaw && !(IDX_RFC[rfcRaw]||[]).length)
      msg = 'El RFC no se encontró en el catálogo. Verifica que esté escrito correctamente.';
    errEl.textContent = msg;
    errEl.style.display = 'block';
    return;
  }

  // Verificar bloqueo
  const bloq = (mejor.bloqueado||'').toLowerCase().includes('seleccionado')
             && !(mejor.bloqueado||'').toLowerCase().includes('no seleccionado');
  if(bloq){
    errEl.textContent = 'Este cliente tiene bloqueo administrativo. Contacta a tu ejecutivo.';
    errEl.style.display = 'block';
    return;
  }

  // ── AUTO-RELLENO del campo faltante ──
  if(!numRaw) $('inp-num').value = mejor.n;
  if(!rfcRaw) $('inp-rfc').value = mejor.rfc || '';
  if(!rsRaw)  $('inp-rs').value  = mejor.rs  || '';

  // Marcar los tres campos como verificados
  ['vdot-0','vdot-1','vdot-2'].forEach(id => $(id).className = 'vdot done');
  $('verify-lbl').textContent = `✓ Cliente verificado con ${mejorScore} de 3 campos`;
  $('verify-lbl').className = 'verify-label ready';

  activarCliente(mejor);
}

function activarCliente(cli){
  state.cliente = cli;
  $('cred-razon-social').value = cli.rs || '';

  const lc   = cli.lc  || 0;
  const sa   = cli.sa  || 0;
  const disp = Math.max(0, lc - sa);
  const bloqTexto = (cli.bloqueado||'').toLowerCase().includes('seleccionado')
                 && !(cli.bloqueado||'').toLowerCase().includes('no seleccionado');

  $('cliente-card').innerHTML = `
    <div class="cliente-card">
      <div class="cli-nombre">
        ${esc(cli.rs)}
        <span style="background:var(--blue-lt);color:var(--blue);border:1px solid #a5b4fc;border-radius:4px;padding:1px 7px;font-size:.73rem;font-weight:700;margin-left:4px">${state.tipoPersona==='fisica'?'Persona Física':'Persona Moral'}</span>
        <span class="${bloqTexto ? 'badge-bloq' : 'badge-activo'}">${bloqTexto ? 'BLOQUEADO' : 'ACTIVO'}</span>
      </div>
      <div class="cli-grid">
        <div class="cli-item"><b>Número:</b> ${esc(cli.n)}</div>
        <div class="cli-item"><b>RFC:</b> ${esc(cli.rfc||'—')}</div>
        <div class="cli-item"><b>Ejecutivo:</b> ${esc(cli.ej||'—')}</div>
        <div class="cli-item"><b>Correo ejecutivo:</b> ${esc(cli.ejCorreo||'—')}</div>
        <div class="cli-item"><b>Línea de crédito:</b> $${fmt(lc)}</div>
        <div class="cli-item"><b>Saldo actual:</b> $${fmt(sa)}</div>
        <div class="cli-item"><b>Crédito disponible:</b> $${fmt(disp)}</div>
      </div>
      <button class="btn-cambiar" onclick="resetBusqueda()">Cambiar cliente</button>
    </div>`;
  $('cliente-card').style.display = 'block';
  $('search-panel').style.display = 'none';

  $('m-lc').textContent        = '$' + fmt(lc);
  $('m-sa').textContent        = '$' + fmt(sa);
  $('m-adicional').textContent  = '—';
  $('m-nueva').textContent      = '—';

  doneSec(1);
  [2,3,4,5].forEach(n => unlockSec(n));
  toast('Cliente verificado: ' + cli.rs, 'ok');
}

function resetBusqueda(){
  state.cliente = null;
  $('search-panel').style.display = 'block';
  $('cliente-card').style.display = 'none';
  $('inp-rs').value = ''; $('inp-num').value = ''; $('inp-rfc').value = '';
  state.tipoPersona = null;
  $('tipo-fisica').classList.remove('selected');
  $('tipo-moral').classList.remove('selected');
  $('tipo-hint').classList.remove('visible');
  $('search-err').style.display = 'none';
  cerrarAC();
  onFieldInput();
  [2,3,4,5].forEach(n=>{
    const hdr = $('shdr-'+n);
    if(hdr){ hdr.classList.add('locked'); hdr.onclick = null; }
    const body = $('sbody-'+n);
    if(body) body.classList.remove('open');
    const num = $('snum-'+n);
    if(num){ num.classList.remove('done'); num.textContent = n; }
  });
}


function esc(s){
  return (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

function actualizarMonto(){
  if(!state.cliente) return;
  const solicitada = parseFloat($('monto-sol').value)||0;
  const lc = state.cliente.lc||0;
  const sa = state.cliente.sa||0;
  const adicional = solicitada > 0 ? solicitada - lc : 0;
  $('m-lc').textContent        = '$' + fmt(lc);
  $('m-sa').textContent        = '$' + fmt(sa);
  $('m-adicional').textContent = solicitada > 0 ? '$' + fmt(adicional) : '—';
  $('m-nueva').textContent     = solicitada > 0 ? '$' + fmt(solicitada) : '—';
}


async function descargarPagare(){
  try{
    const datos = recolectarPagare();
    if(!datos) return;
    const bytes = await generarPagarePDF(datos);
    descargarPDF(bytes, `Pagare_${state.cliente.n}_${fechaArch()}.pdf`);
    toast('Pagaré descargado','ok');
  }catch(e){toast('Error: '+e.message,'er');console.error(e);}
}

function recolectarPagare(){
  if(!state.cliente){toast('Busca tu cliente primero','er');return null;}
  const monto = parseFloat($('monto-sol').value)||0;
  if(monto<=0){toast('Captura el monto solicitado','er');return null;}
  const v=id=>{const el=$(id);return el?el.value.trim():'';}
  const meses=['enero','febrero','marzo','abril','mayo','junio',
    'julio','agosto','septiembre','octubre','noviembre','diciembre'];
  const hoy=new Date();
  const fechaExp=`${hoy.getDate()} de ${meses[hoy.getMonth()]} de ${hoy.getFullYear()}`;
  const venc=new Date(hoy.getFullYear()+1,hoy.getMonth(),hoy.getDate());
  const fechaVenc=`${venc.getDate()} de ${meses[venc.getMonth()]} de ${venc.getFullYear()}`;
  const razon=v('cred-razon-social')||state.cliente.rs||'__________________';
  const solNombre=[v('cred-sol-nombres'),v('cred-sol-paterno'),v('cred-sol-materno')].filter(Boolean).join(' ');
  const domSol=armarDir({calle:v('cred-sol-calle'),numext:v('cred-sol-numext'),
    numint:v('cred-sol-numint'),colonia:v('cred-sol-colonia'),ciudad:v('cred-sol-ciudad'),
    estado:v('cred-sol-estado'),cp:v('cred-sol-cp'),pais:v('cred-sol-pais')});
  const avalNombre=[v('cred-aval-nombres'),v('cred-aval-paterno'),v('cred-aval-materno')].filter(Boolean).join(' ');
  const domAval=armarDir({calle:v('cred-aval-calle'),numext:v('cred-aval-numext'),
    numint:v('cred-aval-numint'),colonia:v('cred-aval-colonia'),ciudad:v('cred-aval-ciudad'),
    estado:v('cred-aval-estado'),cp:v('cred-aval-cp'),pais:v('cred-aval-pais')});
  return {
    tipoPersona: state.tipoPersona,
    lugarExp:'Zapopan, Jalisco',fechaExp,
    beneficiario:'Papel, Diseño y Color S.A. de C.V.',
    domBen:'Avenida del Tigre 2005, Col. Hogares de Nuevo México, Zapopan, Jalisco, C.P. 45138',
    razon,rfcDeudor:(state.cliente.rfc||'').toUpperCase(),
    domDeudor:domSol||'(domicilio no capturado)',
    solNombre:solNombre||'__________________',
    monto,montoFmt:monto.toLocaleString('es-MX',{minimumFractionDigits:2,maximumFractionDigits:2}),
    montoLetra:numeroALetras(monto),fechaVenc,
    tasaMoratoria:'2',jurisdiccion:'Zapopan, Jalisco',
    avalNombre:avalNombre||'__________________',domAval:domAval||'__________________',
  };
}

// ── MEMBRETE ───────────────────────────────────────────────────────────────
const MBR = {
  W:612, H:792, MX:48,          // página y márgenes
  LOGO_W:68, LOGO_TOP:12,       // logo: 68pt ancho, 12pt desde arriba
  HDR_Y:712,                    // línea separadora header
  FTR_Y:54,                     // línea separadora footer
  BODY_TOP:704,                  // primer Y usable de contenido
  BODY_BTM:64,                  // último Y usable de contenido
};

async function prepMbr(doc) {
  const {StandardFonts} = PDFLib;
  const fn  = await doc.embedFont(StandardFonts.Helvetica);
  const fnB = await doc.embedFont(StandardFonts.HelveticaBold);
  const src = document.querySelector('.hdr-logo').src;
  const b64 = src.split(',')[1];
  const raw = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
  const logo = await doc.embedJpg(raw);
  return {fn, fnB, logo};
}

function drawMbr(page, {fn, logo}) {
  const {rgb} = PDFLib;
  const {W, H, MX, LOGO_W, LOGO_TOP, HDR_Y, FTR_Y} = MBR;
  const gray = rgb(.55,.55,.55), grayT = rgb(.4,.4,.4);

  // Logo centrado
  const lH = Math.round(logo.height * LOGO_W / logo.width);
  page.drawImage(logo, {x:(W-LOGO_W)/2, y:H-LOGO_TOP-lH, width:LOGO_W, height:lH});

  // Línea header
  page.drawLine({start:{x:MX,y:HDR_Y}, end:{x:W-MX,y:HDR_Y}, thickness:.75, color:gray});

  // Línea footer
  page.drawLine({start:{x:MX,y:FTR_Y}, end:{x:W-MX,y:FTR_Y}, thickness:.75, color:gray});

  // Footer texto
  const f1 = 'Papel, Dise\u00F1o y Color S.A. de C.V.';
  const f2 = 'Calle Av. del tigre 2005 Col. Hogares de Nuevo M\u00E9xico, Zapopan, Jalisco, 45138  Tel: (33) 3365-1230';
  page.drawText(f1, {x:(W-fn.widthOfTextAtSize(f1,8.5))/2, y:40, font:fn, size:8.5, color:grayT});
  page.drawText(f2, {x:(W-fn.widthOfTextAtSize(f2,7))/2,   y:27, font:fn, size:7,   color:grayT});
}

// ── PAGARÉ ─────────────────────────────────────────────────────────────────
async function generarPagarePDF(d) {
  const {PDFDocument} = PDFLib;
  const doc = await PDFDocument.create();
  const mbr = await prepMbr(doc);
  const {fn, fnB} = mbr;
  const {W, MX, BODY_TOP, BODY_BTM} = MBR;
  const cW = W - 2*MX;

  const page = doc.addPage([W, MBR.H]);
  drawMbr(page, mbr);

  // ── Título
  let y = BODY_TOP - 10;
  const titTxt = 'PAGAR\u00C9';
  page.drawText(titTxt, {x:(W-fnB.widthOfTextAtSize(titTxt,20))/2, y, font:fnB, size:20});
  y -= 18;
  const amtTxt = `Bueno por: $${d.montoFmt} M.N.`;
  page.drawText(amtTxt, {x:W-MX-fnB.widthOfTextAtSize(amtTxt,11), y, font:fnB, size:11});
  y -= 22;

  // ── Cuerpo
  const cuerpo = `En ${d.lugarExp}, a ${d.fechaExp}.

Por el presente pagar\u00E9, ${d.razon}, con domicilio en ${d.domDeudor} y RFC ${d.rfcDeudor}, me obligo incondicionalmente a pagar a la orden de ${d.beneficiario}, con domicilio en ${d.domBen}, la cantidad de $${d.montoFmt} M.N. (${d.montoLetra}), en ${d.domBen}, el d\u00EDa ${d.fechaVenc}.

Esta cantidad la recib\u00ED a mi entera satisfacci\u00F3n.

En caso de mora, este pagar\u00E9 causar\u00E1 un inter\u00E9s moratorio de ${d.tasaMoratoria}% mensual sobre el monto adeudado, computado por d\u00EDas naturales, a partir del d\u00EDa siguiente al vencimiento y hasta el d\u00EDa de su pago total.

Para el caso de incumplimiento en el pago de este pagar\u00E9, el suscriptor se obliga a pagar gastos y costas de cobranza, incluyendo honorarios legales.

El presente documento es t\u00EDtulo ejecutivo conforme a la Ley General de T\u00EDtulos y Operaciones de Cr\u00E9dito.

El deudor y el aval se someten expresamente a la jurisdicci\u00F3n de los tribunales de ${d.jurisdiccion}, renunciando a cualquier otro fuero que pudiera corresponderles por raz\u00F3n de su domicilio presente o futuro. El aval responde solidariamente como obligado principal.`;

  const SIG_RESERVE = 110; // espacio para bloques de firma
  const lns = wordWrap(cuerpo, fn, 10, cW);
  for (const ln of lns) {
    if (y < BODY_BTM + SIG_RESERVE) break;
    page.drawText(ln, {x:MX, y, font:fn, size:10});
    y -= 14;
  }

  // ── Bloques de firma
  const sigY = Math.max(BODY_BTM + SIG_RESERVE - 10, y - 16);
  const colD = MX, colA = MX + Math.floor(cW/2) + 10, colW = Math.floor(cW/2) - 10;

  const drawBlock = (cx, titulo, datos, startY) => {
    let yy = startY;
    page.drawText(titulo, {x:cx, y:yy, font:fnB, size:10});
    yy -= 14;
    for (const item of datos) {
      for (const wl of wordWrap(item, fn, 8.5, colW)) {
        page.drawText(wl, {x:cx, y:yy, font:fn, size:8.5});
        yy -= 12;
      }
    }
    return yy;
  };

  const esFisica = d.tipoPersona === 'fisica';
  const dD = esFisica
    ? [d.solNombre, `RFC: ${d.rfcDeudor}`, `Domicilio: ${d.domDeudor}`]
    : [d.razon, `RFC: ${d.rfcDeudor}`, `Domicilio: ${d.domDeudor}`, `representada por ${d.solNombre}`, 'Apoderado Legal'];
  const dA = [d.avalNombre, `Domicilio: ${d.domAval}`];

  const yD = drawBlock(colD, 'DEUDOR', dD, sigY);
  const yA = drawBlock(colA, 'AVAL',   dA, sigY);

  const lD = Math.min(yD, yA) - 24;
  page.drawLine({start:{x:colD,y:lD}, end:{x:colD+180,y:lD}, thickness:.5});
  page.drawText(esFisica ? 'Firma del Deudor' : 'Firma del Apoderado Legal', {x:colD+(esFisica?30:10), y:lD-13, font:fn, size:9});
  page.drawLine({start:{x:colA,y:lD}, end:{x:colA+180,y:lD}, thickness:.5});
  page.drawText('Firma del Aval',   {x:colA+40, y:lD-13, font:fn, size:9});

  return await doc.save();
}

// ── CARÁTULA ───────────────────────────────────────────────────────────────
function wordWrap(text,font,size,maxWidth){
  const lines=[];
  for(const p of text.split('\n')){
    if(!p.trim()){lines.push('');continue;}
    let cur='';
    for(const w of p.split(' ')){
      const t=cur?cur+' '+w:w;
      if(font.widthOfTextAtSize(t,size)>maxWidth&&cur){lines.push(cur);cur=w;}
      else cur=t;
    }
    if(cur) lines.push(cur);
  }
  return lines;
}

function numeroALetras(n){
  const e=Math.floor(n),c=Math.round((n-e)*100);
  return `${enteroALetras(e)} PESOS ${String(c).padStart(2,'0')}/100 M.N.`;
}
function enteroALetras(n){
  if(!n)return'CERO';
  const U=['','UN','DOS','TRES','CUATRO','CINCO','SEIS','SIETE','OCHO','NUEVE'];
  const E=['DIEZ','ONCE','DOCE','TRECE','CATORCE','QUINCE','DIECISÉIS','DIECISIETE','DIECIOCHO','DIECINUEVE'];
  const D=['','','VEINTI','TREINTA','CUARENTA','CINCUENTA','SESENTA','SETENTA','OCHENTA','NOVENTA'];
  const C=['','CIENTO','DOSCIENTOS','TRESCIENTOS','CUATROCIENTOS','QUINIENTOS','SEISCIENTOS','SETECIENTOS','OCHOCIENTOS','NOVECIENTOS'];
  function l3(x){
    if(!x)return'';if(x===100)return'CIEN';
    let r='';const c=Math.floor(x/100),dy=x%100,dec=Math.floor(dy/10),u=dy%10;
    if(c)r+=C[c]+' ';
    if(dy>=10&&dy<=19)r+=E[dy-10];
    else if(dec===2)r+=(u?'VEINTI'+U[u]:'VEINTE');
    else if(dec>2){r+=D[dec];if(u)r+=' Y '+U[u];}
    else if(u)r+=U[u];
    return r.trim();
  }
  let r='';
  const M=Math.floor(n/1000000),K=Math.floor((n%1000000)/1000),R=n%1000;
  if(M)r+=(M===1?'UN MILLÓN':l3(M)+' MILLONES')+' ';
  if(K)r+=(K===1?'MIL':l3(K)+' MIL')+' ';
  if(R)r+=l3(R);
  return r.trim().replace(/\s+/g,' ');
}

async function generarCaratula(info) {
  const {PDFDocument, rgb} = PDFLib;
  const doc = await PDFDocument.create();
  const mbr = await prepMbr(doc);
  const {fn, fnB} = mbr;
  const {W, MX, BODY_TOP, BODY_BTM} = MBR;
  const cW = W - 2*MX;
  const azul = rgb(0, 0.08, 0.63);

  const page = doc.addPage([W, MBR.H]);
  drawMbr(page, mbr);

  let y = BODY_TOP - 10;

  // Título
  page.drawText('SOLICITUD DE EXTENSI\u00D3N', {x:MX, y, font:fnB, size:16, color:azul});
  y -= 18;
  page.drawText('DE L\u00CDNEA DE CR\u00C9DITO', {x:MX, y, font:fnB, size:16, color:azul});
  y -= 14;
  page.drawText('Cat\u00E1logo Siman \u2014 Clientes vigentes', {x:MX, y, font:fn, size:9, color:rgb(.4,.4,.4)});
  y -= 7;
  page.drawLine({start:{x:MX,y}, end:{x:W-MX,y}, thickness:1.2, color:azul});
  y -= 18;

  // Función de fila (label izquierda, valor derecho del label)
  const LABEL_X = MX, VAL_X = MX + 185, ROW_H = 19;
  const row = (label, val) => {
    if (y < BODY_BTM + 4) return;
    page.drawText(label, {x:LABEL_X, y, font:fnB, size:9,  color:rgb(.35,.35,.35)});
    const wrapped = wordWrap(String(val), fn, 10, cW - 185);
    for (let i=0; i<wrapped.length; i++) {
      if (y < BODY_BTM + 4) break;
      page.drawText(wrapped[i], {x:VAL_X, y, font:fn, size:10});
      if (i < wrapped.length-1) y -= 13;
    }
    y -= ROW_H;
  };

  const hoy = new Date();
  row('Fecha de solicitud:',       hoy.toLocaleDateString('es-MX'));
  row('N\u00FAmero de cliente:',   state.cliente.n);
  row('Tipo de persona:', state.tipoPersona==='fisica'?'Persona F\u00EDsica':'Persona Moral');
  row('Nombre / Raz\u00F3n social:', info.razon);
  row('RFC:',                      state.cliente.rfc || '\u2014');
  row('Ejecutivo asignado:',       state.cliente.ej  || '\u2014');
  row('Solicitante (firmante):',   info.solNombre);
  row('Correo del firmante:',      info.solEmail);
  row('Tel\u00E9fono del firmante:', info.solTel);
  row('Aval:',                     info.avalNombre);

  y -= 6;
  page.drawText('RESUMEN FINANCIERO', {x:MX, y, font:fnB, size:12, color:azul});
  y -= 6;
  page.drawLine({start:{x:MX,y}, end:{x:W-MX,y}, thickness:.5, color:rgb(.8,.8,.8)});
  y -= 15;

  const lc = state.cliente.lc||0, sa = state.cliente.sa||0;
  const sol = info.monto;
  const fmt2 = n => n.toLocaleString('es-MX',{minimumFractionDigits:2});
  row('L\u00EDnea de cr\u00E9dito actual:', '$' + fmt2(lc));
  row('Saldo actual:',                       '$' + fmt2(sa));
  row('Nueva l\u00EDnea de cr\u00E9dito solicitada:', '$' + fmt2(sol));
  row('L\u00EDnea adicional:',               '$' + fmt2(sol - lc));

  return await doc.save();
}

// ── IMAGEN / PDF → PDF CON MEMBRETE ────────────────────────────────────────
async function imgOPdfABytes(file, titulo) {
  const {PDFDocument, rgb} = PDFLib;
  const azul = rgb(0, 0.08, 0.63);
  const buf  = await file.arrayBuffer();
  const {W, MX, BODY_TOP, BODY_BTM} = MBR;
  const bW = W - 2*MX;
  const bH = BODY_TOP - BODY_BTM - 20; // 20pt para el título

  const doc = await PDFDocument.create();
  const mbr = await prepMbr(doc);
  const {fn, fnB} = mbr;

  const isPdf = file.type === 'application/pdf' || /\.pdf$/i.test(file.name);

  if (isPdf) {
    // Embebe cada página del PDF dentro del membrete
    const embedded = await doc.embedPdf(buf);
    for (const ep of embedded) {
      const pg = doc.addPage([W, MBR.H]);
      drawMbr(pg, mbr);
      // Título solo en primera página
      if (doc.getPageCount() === 1) {
        pg.drawText(titulo, {x:MX, y:BODY_TOP-2, font:fnB, size:10, color:azul});
      }
      const sc = Math.min(bW/ep.width, bH/ep.height, 1);
      const eW = ep.width*sc, eH = ep.height*sc;
      pg.drawPage(ep, {
        x: MX + (bW-eW)/2,
        y: BODY_BTM + (bH-eH)/2 + 4,
        width: eW, height: eH
      });
    }
  } else {
    // Imagen JPG / PNG
    const img = (file.type==='image/png'||/\.png$/i.test(file.name))
      ? await doc.embedPng(buf)
      : await doc.embedJpg(buf);
    const pg = doc.addPage([W, MBR.H]);
    drawMbr(pg, mbr);
    pg.drawText(titulo, {x:MX, y:BODY_TOP-2, font:fnB, size:10, color:azul});
    const sc = Math.min(bW/img.width, bH/img.height, 1);
    const iW = img.width*sc, iH = img.height*sc;
    pg.drawImage(img, {
      x: MX + (bW-iW)/2,
      y: BODY_BTM + (bH-iH)/2 + 4,
      width: iW, height: iH
    });
  }

  return await doc.save();
}



async function mergePDFs(arr){
  const {PDFDocument}=PDFLib;
  const m=await PDFDocument.create();
  for(const b of arr){
    const s=await PDFDocument.load(b);
    const ps=await m.copyPages(s,s.getPageIndices());
    ps.forEach(p=>m.addPage(p));
  }
  return await m.save();
}

function descargarPDF(bytes,nombre){
  const blob=new Blob([bytes],{type:'application/pdf'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download=nombre;a.click();URL.revokeObjectURL(url);
}

function fechaArch(){
  const d=new Date();
  return `${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}`;
}

// ── PROCESAR ──
async function procesarSolicitud(){
  const err=$('footer-err');err.textContent='';
  const v=id=>{const el=$(id);return el?el.value.trim():'';}
  if(!state.cliente){err.textContent='Busca y verifica tu número de cliente.';return;}
  const monto=parseFloat($('monto-sol').value)||0;
  if(monto<=0){err.textContent='Captura el monto de crédito solicitado.';return;}
  const razon=v('cred-razon-social'),solN=v('cred-sol-nombres'),solP=v('cred-sol-paterno');
  const solEmail=v('cred-sol-email'),solTelRaw=v('cred-sol-tel').replace(/\D/g,'');
  const solCalle=v('cred-sol-calle'),solNext=v('cred-sol-numext'),solCol=v('cred-sol-colonia');
  const solCiu=v('cred-sol-ciudad'),solEdo=v('cred-sol-estado'),solCP=v('cred-sol-cp'),solPais=v('cred-sol-pais');
  if(!razon){err.textContent='Captura el nombre de la persona moral o física.';return;}
  if(!solN||!solP){err.textContent='Captura nombres y apellido paterno del solicitante.';return;}
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(solEmail)){err.textContent='Correo inválido.';return;}
  if(solTelRaw.length!==10){err.textContent='El teléfono debe tener 10 dígitos.';return;}
  if(!solCalle||!solNext||!solCol||!solCiu||!solEdo||!solCP||!solPais){
    err.textContent='Completa todos los campos de dirección del solicitante.';return;}
  const avalN=v('cred-aval-nombres'),avalP=v('cred-aval-paterno');
  const avalCalle=v('cred-aval-calle'),avalNext=v('cred-aval-numext'),avalCol=v('cred-aval-colonia');
  const avalCiu=v('cred-aval-ciudad'),avalEdo=v('cred-aval-estado'),avalCP=v('cred-aval-cp'),avalPais=v('cred-aval-pais');
  if(!avalN||!avalP){err.textContent='Captura nombres y apellido paterno del aval.';return;}
  if(!avalCalle||!avalNext||!avalCol||!avalCiu||!avalEdo||!avalCP||!avalPais){
    err.textContent='Completa todos los campos de dirección del aval.';return;}
  const ineFr=$('cred-ine-frente').files[0],ineRv=$('cred-ine-reverso').files[0];
  const compr=$('cred-comprobante').files[0];
  const avIneFr=$('cred-aval-ine-frente').files[0],avIneRv=$('cred-aval-ine-reverso').files[0];
  const pagFirm=$('cred-pagare-firmado').files[0];
  if(!ineFr||!ineRv||!compr){err.textContent='Adjunta INE frente, reverso y comprobante del solicitante.';return;}
  if(!avIneFr||!avIneRv){err.textContent='Adjunta INE frente y reverso del aval.';return;}
  const avComp=$('cred-aval-comprobante').files[0];
  if(!avComp){err.textContent='Adjunta el comprobante de domicilio del aval.';return;}
  const poder=$('cred-poder').files[0];
  if(state.tipoPersona==='moral'&&!poder){err.textContent='Adjunta el poder del representante (acta constitutiva).';return;}
  if(!pagFirm){err.textContent='Sube el pagaré firmado.';return;}
  const btn=$('btn-submit');btn.disabled=true;btn.textContent='Generando expediente…';
  try{
    const solFull=[solN,solP,v('cred-sol-materno')].filter(Boolean).join(' ');
    const avalFull=[avalN,avalP,v('cred-aval-materno')].filter(Boolean).join(' ');
    const telFmt='('+solTelRaw.substring(0,2)+') '+solTelRaw.substring(2,6)+' '+solTelRaw.substring(6,10);
    const partes=[];
    partes.push(await generarCaratula({razon,solNombre:solFull,solEmail,solTel:telFmt,avalNombre:avalFull,monto}));
    partes.push(await imgOPdfABytes(ineFr,'INE solicitante — frente'));
    partes.push(await imgOPdfABytes(ineRv,'INE solicitante — reverso'));
    partes.push(await imgOPdfABytes(compr,'Comprobante de domicilio'));
    if(state.tipoPersona==='moral' && poder) partes.push(await imgOPdfABytes(poder,'Poder del representante'));
    partes.push(await imgOPdfABytes(avIneFr,'INE aval — frente'));
    partes.push(await imgOPdfABytes(avIneRv,'INE aval — reverso'));
    partes.push(await imgOPdfABytes(avComp,'Comprobante de domicilio del aval'));
    partes.push(await imgOPdfABytes(pagFirm,'Pagaré firmado físicamente'));
    const final=await mergePDFs(partes);
    const fname=`SolicitudCredito_${state.cliente.n}_${fechaArch()}.pdf`;
    descargarPDF(final,fname);
    const ej=state.cliente.ejCorreo||'—';
    showModal('✓ Solicitud generada',`
      <p>Tu solicitud se descargó como <strong>${fname}</strong>.</p>
      <div class="hl-box">
        Envíala por correo a <a href="mailto:adgomez@padcolor.com"><strong>adgomez@padcolor.com</strong></a>
        con copia a <a href="mailto:jlogistica@padcolor.com"><strong>jlogistica@padcolor.com</strong></a>
        y a tu ejecutivo: <a href="mailto:${ej}"><strong>${ej}</strong></a>.
      </div>
      <p>Con estos documentos tramitamos tu extensión de crédito. Te haremos llegar una guía para que mandes el Pagaré en original.</p>`);
  }catch(e){err.textContent='Error al generar: '+e.message;console.error(e);}
  finally{btn.disabled=false;btn.textContent='Generar y descargar solicitud →';}
}
</script>
</body>
</html>
